CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'citizen',eco_points INT NOT NULL DEFAULT 100,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,product_id VARCHAR(100) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL,category VARCHAR(100),owner_id INT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS product_events (id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,event_type VARCHAR(60) NOT NULL,location TEXT,notes TEXT,created_by INT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS smart_bins (id SERIAL PRIMARY KEY,bin_code VARCHAR(50) UNIQUE NOT NULL,location TEXT,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,fill_level NUMERIC(5,2) DEFAULT 0,temperature NUMERIC(6,2),waste_type VARCHAR(80),battery NUMERIC(5,2),status VARCHAR(20) DEFAULT 'normal',last_updated TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS waste_incidents (id SERIAL PRIMARY KEY,product_id INT REFERENCES products(id) ON DELETE SET NULL,user_id INT REFERENCES users(id) ON DELETE SET NULL,waste_type VARCHAR(100),location TEXT,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,severity VARCHAR(20) DEFAULT 'medium',confidence NUMERIC(5,4),image_url TEXT,status VARCHAR(30) DEFAULT 'reported',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS waste_records (id SERIAL PRIMARY KEY,bin_id INT REFERENCES smart_bins(id) ON DELETE SET NULL,waste_type VARCHAR(100),weight_kg NUMERIC(10,2),collected_at TIMESTAMPTZ DEFAULT NOW());
